#[derive(Debug, PartialEq)]
pub enum Maturidade {
    Suave,
    Maturado,
    Extra,
}

pub fn a_etiqueta_de(dias: i32) -> Maturidade {
    if dias < 2 {
        Maturidade::Suave
    } else if dias < 4 {
        Maturidade::Maturado
    } else {
        Maturidade::Extra
    }
}

