use desafio::a_etiqueta_de;
use desafio::Maturidade;

#[test]
fn testa_a_etiqueta_do_dia_zero() {
    assert_eq!(a_etiqueta_de(0), Maturidade::Suave);
}

#[test]
fn testa_a_etiqueta_do_dia_tres() {
    assert_eq!(a_etiqueta_de(3), Maturidade::Maturado);
}

#[test]
fn testa_a_etiqueta_do_dia_sete() {
    assert_eq!(a_etiqueta_de(7), Maturidade::Extra);
}
